//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** @author John Miller * @version 2.0 * @date Sun Sep 26 15:00:24 EDT 2021 * @see LICENSE (MIT style license file). * * @note Example Model: One-Way-Street (with Vehicle) for Process-Interaction Simulation */
package scalation package simulation package process package example_1 // One-Shot
import scalation.modeling.FitM import scalation.random._ import scalation.mathstat._ import scala.math.abs
@main def runOneWayVehicle2L(): Unit = new OneWayVehicle2L()
class OneWayVehicle2L(name: String = "OneWayVehicle2L", reps: Int = 1, animating: Boolean = true, aniRatio: Double = 500.0, stream: Int = 0) extends Model(name, reps, animating, aniRatio) with RowTimeLoader with FitM:
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Debugging and traffic data loading */ private val debug = debugf("OneWayVehicle2L", false) private val trafficData = new TrafficConfig("/15min_US101_N_Willow_to_Marsh_2miles_ML/400981.csv", rowTime, stream) private val nt = trafficData.data.dim
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Simulation dynamics and random variables */ val motion = GippsDynamics val numLanes = 4 val iArrivalRV = Erlang() // val nStop = trafficData.totalArrivalsPerRow.sum.toInt val nStop = trafficData.nStopArray
//::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
/** Delegate per‑source μ lookup to TrafficConfig */ def getMuForSource(idx: Int): VectorD = trafficData.getMuForSource(idx)
setTime(nt * rowTime) // I need my time stamp formatted for easy passing for time calculations and advancement. // 00:00:00 ----> 00.00, 00.15
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Animation coordinates and junction setup */ val (w, h) = (1000, 800) val shift = 20.0
// Use TrafficConfig methods to get coordinates (eliminates redundant GPS loading) val aniCoords_Main = trafficData.getMainlineCoordinates((w, h)) val aniCoords_Ramp = trafficData.getRampCoordinates((w, h))
// Create the classic highway structure: sensor1 to sensor7 (7 junctions, 6 segments)
val main_sensors = Array.ofDim[Junction](aniCoords_Main.length) for i <- main_sensors.indices do main_sensors(i) = new Junction(s"ssor${i}", xy = (aniCoords_Main(i)._1, aniCoords_Main(i)._2), nt = nt)
val ramp_sensors = Array.ofDim[Junction](aniCoords_Ramp.length) for i <- ramp_sensors.indices do ramp_sensors(i) = new Junction(s"ramp${i}", xy = (aniCoords_Ramp(i)._1 + 45, aniCoords_Ramp(i)._2 - 50), nt = nt)
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Define animation center and offsets */ val mainPos = aniCoords_Main(0) val centerPos = ((mainPos._1 + 100.0).toInt, (mainPos._2 + 100.0).toInt) val offsets = Array( (0, 0), ((aniCoords_Ramp(0)._1 + 230.0).toInt - centerPos._1, (aniCoords_Ramp(0)._2 - 300.0).toInt - centerPos._2), ((aniCoords_Ramp(1)._1 + 230.0).toInt - centerPos._1, (aniCoords_Ramp(1)._2 - 300.0).toInt - centerPos._2), ((aniCoords_Ramp(2)._1 + 230.0).toInt - centerPos._1, (aniCoords_Ramp(2)._2 - 300.0).toInt - centerPos._2) )
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Create VSources inline so mySource is bound properly */ val sources = VSource.group(this, () => Car(), centerPos, ("Vsrc", 0, Erlang(), nStop(0), offsets(0)), ("srcRamp1", 1, Erlang(), nStop(1), offsets(1)), ("srcRamp2", 2, Erlang(), nStop(2), offsets(2)), ("srcRamp3", 3, Erlang(), nStop(3), offsets(3)) ) //:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Create Sinks locally for correct mapping and final routing */ val (x0, y0) = aniCoords_Main.last val (x1, y1) = aniCoords_Ramp(3)
val sinks = Sink.group((x0.toInt - 100, y0.toInt - 100), ("sinkMain", (0, 0)), ("sinkRamp", ((x1 + 230.0).toInt - (x0.toInt - 100), (y1 - 300.0).toInt - (y0.toInt - 100))) )
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Create ramps inline to preserve subtype mapping */ val ramps = Ramp.group(motion, ("onRamp1", sources(1), ramp_sensors(0), RampMode.On, 0.0, 0.0), ("onRamp2", sources(2), ramp_sensors(1), RampMode.On, 0.0, 0.0), ("onRamp3", sources(3), ramp_sensors(2), RampMode.On, 0.0, 0.0), ("offRamp", ramp_sensors(3), sinks(1), RampMode.Off, 0.0, 0.0) )
val intermediateJunctions = main_sensors.slice(1, main_sensors.length - 1) val mainRoute = Route("Rte", numLanes, intermediateJunctions, main_sensors(0), main_sensors.last, motion)
addComponents(sources.toList, main_sensors.toList ++ ramp_sensors.toList, sinks.toList, ramps.toList) mainRoute.pathway.foreach(addComponent(_))
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Map each ramp index → segment index on the main route where it merges */ val rampJoinSeg = Array(1, 2, 5) // onRamp1 merges at seg 1, onRamp2 at seg 2, onRamp3 at seg 5 @inline def pos(rampIdx: Int): Int = rampJoinSeg(rampIdx)
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Define the Vehicle subclass with its own act method */ case class Car() extends Vehicle("c", this): override def act(): Unit = Vehicle.setInitialSpeed(68.0 / 2.24694) val laneRV = trafficData.getLaneRV((clock.toInt / rowTime.toInt) % nt) val laneChangeRV = Bernoulli(0.8) // Probability of lane change val offRampRV = Bernoulli(0.8) // Probability of exiting at off-ramp val i = subtype val j = if i == 0 then laneRV.igen else 0 this.laneID = j val highWay = mainRoute val highWaySrc = 0 val highWayExit = sinks(0) val offRampExit = sinks(1) val offRampSegment = 6 // Off-ramp at segment 4 (before last sensor)
if i == highWaySrc then val lane = highWay.pathway(j) // your pathway/lane in this highway val carAhead = lane.getLast // follow the last car in the lane lane.addToAlist(this, carAhead) // add yourself to this lane behind the car ahead
var exited = false // Flag to check if vehicle has exited the off-ramp????// Why should the flag be here??? //vehicle hasn't even moved yet, for seg <- 0 until main_sensors.length - 1 if !exited do if laneChangeRV.gen then // 0.5 probability of changing lanes val current = this.laneID // Current lane ID val target = (current + 1) % numLanes // target lane if highWay.changeLane(current, target, this, seg) then println(s"$this changed from lane $current @ seg:$seg to lane target:$target") end if end if
//a jump is very important event for the car, because that allows the car to upload its data to the sensors. A sensor is a junction //a jump is inside the junction/sensor val currentId = this.laneID val currentLane = highWay.pathway(currentId) currentLane.seg(seg).move() // Move the vehicle in the current segment main_sensors(seg + 1).jump() //take record at the current sensor // a jump is a registered event for the current car
if seg + 1 == offRampSegment && offRampRV then currentLane.removeFromAlist(this) val offRamp = ramps(3) // Off-ramp is index 3 val carAhead = offRamp.getLast offRamp.addToAlist(this, carAhead) ramp_sensors(3).jump() // the sensor/junction is before the transport in the off-ramp offRamp.lane.move() // junction/sensor------(seg)------> offRamp// jump then move then to sink offRamp.removeFromAlist(this) offRampExit.leave() exited = true end if end for
if !exited then highWay.pathway(this.laneID).removeFromAlist(this) highWayExit.leave() // Leave the main route if not exiting at off-ramp end if
else // Ramp vehicles val rampId = i - 1 val ramp = ramps(rampId) val carAhead = ramp.getLast ramp.addToAlist(this, carAhead) ramp.lane.move() ramp_sensors(rampId).jump() ramp.removeFromAlist(this)
// Merge onto main route at the joining segment this.laneID = 0 // Merge into rightmost lane val joinSeg = pos(rampId) val mergeLane = highWay.pathway(0) val carAheadMain = mergeLane.getLast mergeLane.addToAlist(this, carAheadMain)
var exited = false for seg <- joinSeg until main_sensors.length - 1 if !exited do // this still look like the vehicle will travers all intermeidate junctions. should be the junction they join from only val currentLane = highWay.pathway(this.laneID) currentLane.seg(seg).move() main_sensors(seg + 1).jump()
if seg == offRampSegment && offRampRV then currentLane.removeFromAlist(this) val offRamp = ramps(3) // Off-ramp is index 3 val carAhead = offRamp.getLast offRamp.addToAlist(this, carAhead) ramp_sensors(3).jump() offRamp.lane.move() offRamp.removeFromAlist(this) offRampExit.leave() exited = true end if end for
if !exited then highWay.pathway(this.laneID).removeFromAlist(this) highWayExit.leave() end if end if end Car
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Compute SMAPE between simulation and PEMS data *Need to add the ramp sensors to this */ def simRunVsPemsRun(): Double = val ytrue = trafficData.totalArrivalsPerRow val scores = for sensor <- main_sensors ++ ramp_sensors yield smapeF(ytrue, sensor.getCountMatrix.sumVr) scores.sum / scores.length end simRunVsPemsRun
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Write stats and finalize simulation */ override def fini(rep: Int): Unit = Recorder.writeAllSensorStats(main_sensors.toList ++ ramp_sensors.toList) simRunVsPemsRun() super.fini(rep) end fini
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Run the simulation */ simulate() waitFinished() Model.shutdown() end OneWayVehicle2L
/** * Create Array structure of components: (An array of Vsources). * Use the same order of the Array to put the Onramps on the road * then access the Sources via Index of the Array such that you can get the correct source at the correct time * No need of the name of the source. We just need to Index. * the substyoe of the Vehicle can help determing the source the vehicle came from * Array(Vsource1, Vsource2): * The Vehcles can enter the pathway via the based on the source and subtype: * Need a Map: -----> which source goes to which pathway via a Junction and the Vsource subtype * Source Index: Map to Pathway Index (junction) ---> Allows Vehicles to know which pathway to take based on the source they came from * junction to Sink for offRamp: Should model same for onRamp * Maybe a configuration file: And this needs to be exposed to Vehicles * * A method that creates this Vsoucres and add them to array then u can use them via the index of the array: Components in a loop * * A config */
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Drive through main route with optional off-ramp exit * Should be based on the cars that trully exit the ramp since we have the on-ramp sensor data.... * We may need a way to model this scene?????? * //if we take 6AM-11AM. How many Vehicles exited at Marsh road? * //Once we have the data, we can use it to model the off-ramp exit probability * //We have to model this true scenerions * Currently we are using an offRampRV Bernoulli distribution to decide if the vehicle exits */
/** Main act method: choose lane and route based on subtype * We have to check the speed of the vehicles * then model the speed based on the data we are feeding the sensors * if we are doing 6AM to 12PM, then we have to model the speed of the vehicles * The data is already available in the sensor file * All we have to do is to also feed this speed same way we are feeding the arrival rate * Maybe the arival rate flow can help wit this speed modeling * Vehicle need to enter onramp or main route * Be added to the path's alist at the start * before you can drive or even change lanes of whats so ever * that logic must be sound and correct */
// The GPS coordinates for the junctions in the OneWayVehicle2L model //37.468732, -122.154696 // 400981 → junc(0) → Mainline entry (Willow)) //37.468732, -122.154696 // 408267 → OnRamp from Willow → junc(1) //37.469590, -122.156168 // 402398 → junc(1) → Mainline //37.469675, -122.156317 // 408264 → OnRamp from Willow → junc(2) //37.472754, -122.161627 // 404534 → junc(2) → Mainline //37.474830, -122.165147 // 401474 → junc(3) → Mainline //37.480426, -122.174688 // 400388 → junc(4) → Mainline //37.482799, -122.179049 // 412784 → OffRamp to Marsh → junc(2) //37.483144, -122.179850 // 401927 → junc(5) → Mainline //37.483144, -122.179850 // 412783 → OnRamp from Marsh → junc(4) //37.483811, -122.181671 // 401653 → junc(6) → Mainline exit (Marsh)

//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** @author John Miller * @version 2.0 * @date Sun Sep 26 15:00:24 EDT 2021 * @see LICENSE (MIT style license file). * * @note Example Model: One-Way-Street (with Vehicle) for Process-Interaction Simulation */
