val sinks = Sink.group((x0.toInt - 100, y0.toInt - 100), ("sinkMain", (0, 0)), ("sinkRamp", ((x1 + 230.0).toInt - (x0.toInt - 100), (y1 - 300.0).toInt - (y0.toInt - 100))) )
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Create ramps inline to preserve subtype mapping */ val ramps = Ramp.group(motion, ("onRamp1", sources(1), ramp_sensors(0), RampMode.On, 0.0, 0.0), ("onRamp2", sources(2), ramp_sensors(1), RampMode.On, 0.0, 0.0), ("onRamp3", sources(3), ramp_sensors(2), RampMode.On, 0.0, 0.0), ("offRamp", ramp_sensors(3), sinks(1), RampMode.Off, 0.0, 0.0) )
