if seg == offRampSegment && offRampRV then currentLane.removeFromAlist(this) val offRamp = ramps(3) // Off-ramp is index 3 val carAhead = offRamp.getLast offRamp.addToAlist(this, carAhead) ramp_sensors(3).jump() offRamp.lane.move() offRamp.removeFromAlist(this) offRampExit.leave() exited = true end if end for
if !exited then highWay.pathway(this.laneID).removeFromAlist(this) highWayExit.leave() end if end if end Car
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Compute SMAPE between simulation and PEMS data *Need to add the ramp sensors to this */ def simRunVsPemsRun(): Double = val ytrue = trafficData.totalArrivalsPerRow val scores = for sensor <- main_sensors ++ ramp_sensors yield smapeF(ytrue, sensor.getCountMatrix.sumVr) scores.sum / scores.length end simRunVsPemsRun
